export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',pen:'m15 5 4 4M4 20l4-1L20 7a3 3 0 0 0-4-4L4 15z',search:'M15 15l6 6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',arrow:'M4 12h16m-6-6 6 6-6 6',file:'M14 3H5v18h14V8zM14 3v6h5M8 13h8m-8 4h6',chart:'M4 3v18h17M8 16v-4m5 4V6m5 10V9',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',menu:'M3 6h18M3 12h18M3 18h18',plus:'M12 4v16M4 12h16',folder:'M3 6h7l2 2h9v12H3zM3 6V4h7l2 2',settings:'m9 3 6 0 1 3 3 1 2 5-2 2v3l-5 3-2-2-3 0-2 2-5-3v-3l-2-2 2-5 3-1zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',user:'M5 21v-3a7 7 0 0 1 14 0v3M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',diamond:'m3 9 4-5h10l4 5-9 12zM3 9h18M7 4l5 17 5-17',bell:'M6 9a6 6 0 0 1 12 0v7l3 2H3l3-2zM10 21h4',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',upload:'M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6',close:'m6 6 12 12M6 18 18 6'};
export const icon=(n,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
export const formatDate=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'本地保存':d.toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});};
export const empty=(message,url,label='开始使用')=>`<div class="hub-empty">${icon('folder',30)}<p>${message}</p>${url?`<a class="btn secondary" href="${esc(url)}">${label}</a>`:''}</div>`;
export function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
